public class DataEncoder {
    private static final Logger log = Logger.getLogger(DataEncoder.class.getName());

    public static String encodeDataItem(Object item) {
        if (item == null) {
            return "null";
        }

        try {
            Method dumpFunc = item.getClass().getMethod("modelDump", boolean.class, boolean.class);
            if (dumpFunc != null) {
                try {
                    Object output = dumpFunc.invoke(item, true, true);
                    return output != null ? output.toString() : "null";
                } catch (Exception ex) {
                    log.warning("Failed to encode data item: " + ex.getMessage());
                    return item.toString();
                }
            }
        } catch (NoSuchMethodException ex) {
        }

        return item.toString();
    }
}

