public class ContextHelper {

    private static final String ADK_CONTEXT_ID_PREFIX = "adk";
    private static final String ADK_CONTEXT_ID_SEPARATOR = "_";

    public static String createA2AContextIdentifier(String projectName, String ownerId, String sessionIdentifier) {
        if (projectName == null || projectName.isEmpty()
                || ownerId == null || ownerId.isEmpty()
                || sessionIdentifier == null || sessionIdentifier.isEmpty()) {
            throw new IllegalArgumentException("All parameters (projectName, ownerId, sessionIdentifier) must be non-empty");
        }

        return String.join(ADK_CONTEXT_ID_SEPARATOR, ADK_CONTEXT_ID_PREFIX, projectName, ownerId, sessionIdentifier);
    }
}

public class ContextHelper {

    private static final String ADK_CONTEXT_ID_PREFIX = "adk";
    private static final String ADK_CONTEXT_ID_SEPARATOR = "_";

    public static String[] parseA2AContextIdentifier(String ctxIdentifier) {
        if (ctxIdentifier == null || ctxIdentifier.isEmpty()) {
            return new String[]{null, null, null};
        }

        try {
            String[] segments = ctxIdentifier.split(ADK_CONTEXT_ID_SEPARATOR);
            if (segments.length != 4) {
                return new String[]{null, null, null};
            }

            String prefix = segments[0];
            String projectName = segments[1];
            String ownerId = segments[2];
            String sessionIdentifier = segments[3];

            if (ADK_CONTEXT_ID_PREFIX.equals(prefix)
                    && projectName != null && !projectName.isEmpty()
                    && ownerId != null && !ownerId.isEmpty()
                    && sessionIdentifier != null && !sessionIdentifier.isEmpty()) {
                return new String[]{projectName, ownerId, sessionIdentifier};
            }
        } catch (Exception ex) {
            // Ignore
        }

        return new String[]{null, null, null};
    }
}

