public class AgentUtil {

    public static Class<? extends BaseAgent> determineAgentType(String agentType) {
        String agentTypeName = (agentType != null && !agentType.isEmpty()) ? agentType : "LlmAgent";

        if (!agentTypeName.contains(".")) {
            agentTypeName = "google.adk.agents." + agentTypeName;
        }

        try {
            Class<?> cls = Class.forName(agentTypeName);
            if (BaseAgent.class.isAssignableFrom(cls)) {
                @SuppressWarnings("unchecked")
                Class<? extends BaseAgent> agentClass = (Class<? extends BaseAgent>) cls;
                return agentClass;
            } else {
                throw new IllegalArgumentException(
                    "Invalid agent type `" + agentTypeName + "`. It must be a subclass of BaseAgent."
                );
            }
        } catch (ClassNotFoundException e) {
            throw new IllegalArgumentException(
                "Invalid agent type `" + agentTypeName + "`. Class not found.", e
            );
        }
    }
}

