public class ReflectionUtil {

    public static Object resolveFullyQualifiedName(String fqName) {
        try {
            int lastDotPos = fqName.lastIndexOf('.');
            if (lastDotPos == -1) {
                throw new IllegalArgumentException("Invalid fully qualified name: " + fqName);
            }

            String className = fqName.substring(0, lastDotPos);
            String memberName = fqName.substring(lastDotPos + 1);

            Class<?> cls = Class.forName(className);
            try {
                return cls.getField(memberName).get(null);
            } catch (NoSuchFieldException e) {
                return cls.getMethod(memberName);
            }
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid fully qualified name: " + fqName, e);
        }
    }
}

public class AgentUtil {

    public static BaseAgent resolveAgentCodeRef(String ref) {
        if (!ref.contains(".")) {
            throw new IllegalArgumentException("Invalid code reference: " + ref);
        }

        int lastDotPos = ref.lastIndexOf('.');
        String clsName = ref.substring(0, lastDotPos);
        String memberName = ref.substring(lastDotPos + 1);

        try {
            Class<?> cls = Class.forName(clsName);
            Object obj;
            try {
                obj = cls.getField(memberName).get(null);
            } catch (NoSuchFieldException e) {
                obj = cls.getMethod(memberName);
            }

            if (obj instanceof java.lang.reflect.Method) {
                throw new IllegalArgumentException("Invalid agent reference to a callable: " + ref);
            }

            if (!(obj instanceof BaseAgent)) {
                throw new IllegalArgumentException("Invalid agent reference to a non-agent instance: " + ref);
            }

            return (BaseAgent) obj;
        } catch (ClassNotFoundException | IllegalAccessException | NoSuchMethodException e) {
            throw new IllegalArgumentException("Invalid agent reference: " + ref, e);
        }
    }
}

public class CodeResolver {

    public static Object determineCodeReference(CodeConfiguration configuration) {
        if (configuration == null || configuration.getName() == null || configuration.getName().isEmpty()) {
            throw new IllegalArgumentException("Invalid CodeConfiguration.");
        }

        String completeName = configuration.getName();
        int finalDotPosition = completeName.lastIndexOf('.');
        if (finalDotPosition == -1) {
            throw new IllegalArgumentException("Invalid CodeConfiguration name: " + completeName);
        }

        String classIdentifier = completeName.substring(0, finalDotPosition);
        String memberIdentifier = completeName.substring(finalDotPosition + 1);

        try {
            Class<?> classObject = Class.forName(classIdentifier);
            Object instance;
            try {
                instance = classObject.getField(memberIdentifier).get(null);
            } catch (NoSuchFieldException exception) {
                instance = classObject.getMethod(memberIdentifier);
            }

            if (configuration.getArguments() != null && instance instanceof Method method) {
                List<Object> positionalArguments = new ArrayList<>();
                Map<String, Object> keywordArguments = new HashMap<>();

                for (CodeArgument argument : configuration.getArguments()) {
                    if (argument.getName() != null) {
                        keywordArguments.put(argument.getName(), argument.getValue());
                    } else {
                        positionalArguments.add(argument.getValue());
                    }
                }

                return method.invoke(null, positionalArguments.toArray());
            } else {
                return instance;
            }
        } catch (Exception exception) {
            throw new IllegalArgumentException("Failed to determine code reference: " + completeName, exception);
        }
    }
}

