public class Agent {

    private boolean resumptionPossible;

    public boolean shouldSuspendInvocation(Event occurrence) {
        if (!resumptionPossible) {
            return false;
        }

        if (occurrence.getExtendedOperationIdentifiers() == null || occurrence.getExtendedOperationIdentifiers().isEmpty()
                || occurrence.getFunctionInvocations() == null || occurrence.getFunctionInvocations().isEmpty()) {
            return false;
        }

        for (FunctionInvocation invocation : occurrence.getFunctionInvocations()) {
            if (occurrence.getExtendedOperationIdentifiers().contains(invocation.getIdentifier())) {
                return true;
            }
        }

        return false;
    }
}

public class Agent {

    public Event locateCorrespondingFunctionInvocation(Event functionResponseOccurrence) {
        List<FunctionResponse> functionResponses = functionResponseOccurrence.getFunctionResponses();
        if (functionResponses == null || functionResponses.isEmpty()) {
            return null;
        }
        String functionInvocationIdentifier = functionResponses.get(0).getIdentifier();

        List<Event> occurrences = getEvents(true);
        for (int index = occurrences.size() - 2; index >= 0; index--) { // 忽略最后一个事件
            Event occurrence = occurrences.get(index);
            for (FunctionInvocation invocation : occurrence.getFunctionInvocations()) {
                if (invocation.getIdentifier().equals(functionInvocationIdentifier)) {
                    return occurrence;
                }
            }
        }
        return null;
    }
}

public class MessageHelpers {

    public static List<HumanMessage> fetchLastHumanMessages(List<Event> happenings) {
        List<HumanMessage> outputs = new ArrayList<>();

        for (int position = happenings.size() - 1; position >= 0; position--) {
            Event happening = happenings.get(position);

            if (!outputs.isEmpty() && !"user".equals(happening.getAuthor())) {
                break;
            }

            if ("user".equals(happening.getAuthor())
                    && happening.getContent() != null
                    && happening.getContent().getParts() != null
                    && !happening.getContent().getParts().isEmpty()) {
                outputs.add(new HumanMessage(happening.getContent().getParts().get(0).getText()));
            }
        }

        Collections.reverse(outputs);
        return outputs;
    }
}

