public class Agent {

    private String label;

    public List<Message> fetchConversationWithAgent(List<Event> happenings) {
        List<Message> conversation = new ArrayList<>();

        for (Event happening : happenings) {
            if (happening.getContent() == null || happening.getContent().getParts() == null
                    || happening.getContent().getParts().isEmpty()) {
                continue;
            }

            String text = happening.getContent().getParts().get(0).getText();

            if ("user".equals(happening.getAuthor())) {
                conversation.add(new HumanMessage(text));
            } else if (label.equals(happening.getAuthor())) {
                conversation.add(new AIMessage(text));
            }
        }

        return conversation;
    }
}

