public class Agent {

    private Object model;
    private Agent parentAgent;
    private String label;

    public BaseLlm standardModel() {
        if (model instanceof BaseLlm) {
            return (BaseLlm) model;
        } else if (model instanceof String && !((String) model).isEmpty()) {
            return LLMRegistry.createLlm((String) model);
        } else {
            Agent ancestor = parentAgent;
            while (ancestor != null) {
                if (ancestor instanceof LlmAgent) {
                    return ((LlmAgent) ancestor).standardModel();
                }
                ancestor = ancestor.parentAgent;
            }
            throw new IllegalStateException("No model located for " + label + ".");
        }
    }
}

public class Agent {

    private List<ToolUnion> implements;
    private Object model;

    public CompletableFuture<List<BaseTool>> standardImplements(ReadonlyContext context) {
        List<BaseTool> fetchedImplements = new ArrayList<>();
        boolean severalImplements = implements.size() > 1;

        List<CompletableFuture<List<BaseTool>>> promises = new ArrayList<>();
        for (ToolUnion toolUnion : implements) {
            promises.add(_transformToolUnionToImplements(toolUnion, context, model, severalImplements));
        }

        return CompletableFuture.allOf(promises.toArray(new CompletableFuture[0]))
                .thenApply(v -> {
                    for (CompletableFuture<List<BaseTool>> promise : promises) {
                        try {
                            fetchedImplements.addAll(promise.get());
                        } catch (Exception error) {
                            throw new RuntimeException(error);
                        }
                    }
                    return fetchedImplements;
                });
    }

    private CompletableFuture<List<BaseTool>> _transformToolUnionToImplements(
            ToolUnion toolUnion, ReadonlyContext context, Object model, boolean severalImplements) {
        return CompletableFuture.completedFuture(new ArrayList<>());
    }

    static class BaseTool {}
    static class ToolUnion {}
    static class ReadonlyContext {}
}

