public class AgentHandler {

    private final BlockingQueue<Pair<Event, CompletableFuture<Void>>> queue = new LinkedBlockingQueue<>();
    private final Pair<Event, CompletableFuture<Void>> terminator = new Pair<>(null, null);

    public void handleAnAgent(AsyncIterable<Event> eventsForSingleAgent) {
        CompletableFuture.runAsync(() -> {
            try {
                for (Event occurrence : eventsForSingleAgent) { // 假设 AsyncIterable 已被封装为可同步迭代
                    CompletableFuture<Void> resumeIndicator = new CompletableFuture<>();
                    queue.put(new Pair<>(occurrence, resumeIndicator));
                    resumeIndicator.get(); // 等待上游处理完成
                }
            } catch (Exception error) {
                throw new RuntimeException(error);
            } finally {
                try {
                    queue.put(terminator);
                } catch (InterruptedException error) {
                    Thread.currentThread().interrupt();
                }
            }
        });
    }

    public static class Pair<K, V> {
        public final K first;
