public String formatOccurrencesForPrompt(List<Event> occurrences) {
    StringBuilder formattedRecord = new StringBuilder();
    for (Event occurrence : occurrences) {
        if (occurrence.getContent() != null && occurrence.getContent().getSegments() != null) {
            for (ContentSegment segment : occurrence.getContent().getSegments()) {
                if (segment.getText() != null) {
                    if (formattedRecord.length() > 0) {
                        formattedRecord.append("\n");
                    }
                    formattedRecord.append(occurrence.getAuthor()).append(": ").append(segment.getText());
                }
            }
        }
    }
    return formattedRecord.toString();
}

