public class ArtifactHelpers {

    public static List<File> iterateArtifactDirectories(File base) {
        List<File> artifactDirectories = new ArrayList<>();
        if (!base.exists() || !base.isDirectory()) {
            return artifactDirectories;
        }

        File[] entries = base.listFiles();
        if (entries == null) {
            return artifactDirectories;
        }

        for (File entry : entries) {
            if (entry.isDirectory()) {
                File versionsDirectory = new File(entry, "versions");
                if (versionsDirectory.exists() && versionsDirectory.isDirectory()) {
                    artifactDirectories.add(entry);
                } else {
                    artifactDirectories.addAll(iterateArtifactDirectories(entry)); // recursively check subdirectories
                }
            }
        }

        return artifactDirectories;
    }
}

