            throw new NotFoundException("Eval set `" + evalSetIdentifier + "` not found.");
        }
        return evalSet;
    }
}

public class EvalSetHelpers {

    public static Optional<EvalCase> fetchEvalCaseFromEvalSet(EvalSet evalSet, String evalCaseIdentifier) {
        if (evalSet == null || evalSet.getEvalCases() == null) {
            return Optional.empty();
        }

        for (EvalCase evalCase : evalSet.getEvalCases()) {
            if (evalCaseIdentifier.equals(evalCase.getEvalId())) {
                return Optional.of(evalCase);
            }
        }

        return Optional.empty();
    }
}
